import gurobipy as gp
from gurobipy import GRB

env = gp.Env(empty=True)
env.setParam('LogFile', 'transport.log')
env.start()

model = gp.Model(env=env)

supply = [[20, 30], [40, 10]]
demand = [[30, 30], [30, 10]]
limit = [[35, 25], [25, 30]]
cost = [[[2, 3], [4, 1]], [[3, 2], [2, 4]]]

x = [[[None for _ in range(2)] for _ in range(2)] for _ in range(2)]
for i in range(2):
    for j in range(2):
        for p in range(2):
            x[i][j][p] = model.addVar(vtype=GRB.CONTINUOUS, name=f'x_{i}_{j}_{p}')

for i in range(2):
    for p in range(2):
        expr = 0.0
        for j in range(2):
            expr += x[i][j][p]
        model.addConstr(expr == supply[i][p], f'supply_{i}_{p}')

for j in range(2):
    for p in range(2):
        expr = 0.0
        for i in range(2):
            expr += x[i][j][p]
        model.addConstr(expr == demand[j][p], f'demand_{j}_{p}')

for i in range(2):
    for j in range(2):
        expr = 0.0
        for p in range(2):
            expr += x[i][j][p]
        model.addConstr(expr <= limit[i][j], f'limit_{i}_{j}')

obj_expr = 0.0
for i in range(2):
    for j in range(2):
        for p in range(2):
            obj_expr += cost[i][j][p] * x[i][j][p]
model.setObjective(obj_expr, GRB.MINIMIZE)

model.optimize()

if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
