import gurobipy as gp
from gurobipy import GRB

participants = ["P1", "P2", "P3"]
cars = ["C1", "C2", "C3"]
possible_assignments = [[1, 0, 1], [0, 1, 0], [1, 1, 1]]

model = gp.Model()

x = {}
for p in participants:
    for c in cars:
        x[(p, c)] = model.addVar(vtype=GRB.BINARY, name=f"x_{p}_{c}")

objective_terms = []
for p in participants:
    for c in cars:
        idx_p = participants.index(p)
        idx_c = cars.index(c)
        val = possible_assignments[idx_p][idx_c]
        if val == 1:
            objective_terms.append(x[(p, c)])
model.setObjective(sum(objective_terms), GRB.MAXIMIZE)

for p in participants:
    for c in cars:
        idx_p = participants.index(p)
        idx_c = cars.index(c)
        val = possible_assignments[idx_p][idx_c]
        model.addConstr(x[(p, c)] <= val)

model.optimize()

if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
